{"path":"tools/LetUsCook.AutoWrongCensus/Options/CommandLineArgumentParser.cs","content":"namespace LetUsCook.AutoWrongCensus.Options;

/// <summary>
/// Positional subcommand parser: <c>census &lt;trace.jsonl&gt;</c> and
/// <c>pairs &lt;census.tsv&gt; &lt;trace.jsonl&gt;</c>. Anything else parses to an empty
/// dictionary; the runner prints the usage and exits 1.
/// </summary>
public static class CommandLineArgumentParser
{
	public static Dictionary<string, string?> Parse(string[] args)
	{
		ArgumentNullException.ThrowIfNull(args);
		var dict = new Dictionary<string, string?>(StringComparer.OrdinalIgnoreCase);

		if (args.Length == 0)
		{
			return dict;
		}

		var command = args[0];
		if (command.Equals("census", StringComparison.OrdinalIgnoreCase))
		{
			if (args.Length != 2)
			{
				return dict;
			}

			dict["AutoWrongCensus:Command"] = "census";
			dict["AutoWrongCensus:TracePath"] = args[1];
		}
		else if (command.Equals("pairs", StringComparison.OrdinalIgnoreCase))
		{
			if (args.Length != 3)
			{
				return dict;
			}

			dict["AutoWrongCensus:Command"] = "pairs";
			dict["AutoWrongCensus:CensusTsvPath"] = args[1];
			dict["AutoWrongCensus:TracePath"] = args[2];
		}

		return dict;
	}
}
