		Console.WriteLine();
		Console.WriteLine("Usage:");
		Console.WriteLine("  census <trace.jsonl>");
		Console.WriteLine("      Classify every auto-wrong line (auto == true && correct == false) of a");
		Console.WriteLine("      debug/batch HoldoutGate trace by relation (accepted row vs key row) and");
		Console.WriteLine("      site (reuse, override, curated, ranker). TSV on stdout, summary on stderr.");
		Console.WriteLine();
		Console.WriteLine("  pairs <census.tsv> <trace.jsonl>");
		Console.WriteLine("      For each census row with blocker=window and route=compound|other, emit the");
		Console.WriteLine("      parsedName head and the key head-phrase words.");
		Console.WriteLine();
