{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on two axes — relation (accepted row vs key row) and site
/// (where the line was accepted) — using the production helpers, never a copy of them (D-014):
/// <see cref="FdcNormalizer.NormalizeToTokens"/>, <see cref="FdcMatcher.ExtractCandidateState"/>,
/// <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>, <see cref="FdcDescriptionParser.Parse"/>,
/// <see cref="IngredientLineResolver.SingularizeToken"/> and <see cref="IngredientLineResolver.ShouldReuse"/>.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation: the labelled row is empty.</summary>
	public const string NoLabel = "no-label";

	/// <summary>Relation: a can/jar unit in the raw line, the key row is canned, the accepted row is not.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>Relation: the key's head phrase has two or more words and the parsed name keeps only its first.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: the head terms agree and the state masks differ.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>Relation: head and state agree and the dataset tier differs.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>Relation: head, state and tier agree and only the qualifiers differ.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the head terms differ.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Relation: nothing above held, or a field the rule needs is missing from the trace.</summary>
	public const string Other = "other";

	/// <summary>Site: the line reused an existing row through the ranker path.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the line was accepted through the override path.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the line was accepted through the curated catalogue.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the line was accepted by the ranker without reuse.</summary>
	public const string SiteRanker = "ranker";

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Reused for the per-token state probe so the classifier allocates nothing per token.
	private readonly List<string> _singleToken = [];

	/// <summary>Creates the classifier.</summary>
	/// <param name="normalizer">The production token normalizer.</param>
	/// <param name="overrideKeys">The exact-overrides.json key index.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	/// <summary>
	/// A can or jar unit in the raw line: the words <c>can</c>/<c>cans</c>/<c>jar</c>/<c>jars</c> on word
	/// boundaries, which covers the "(N ounce) can" shape as well.
	/// </summary>
	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	/// <summary>
	/// Classifies one auto-wrong line. The first relation that holds wins, in the brief's order:
	/// no-label, pack-unit-state, compound-head-lost, state-mismatch, row-choice-tier,
	/// same-head-other-qualifier, sibling-food, other.
	/// </summary>
	/// <param name="line">The trace line (<c>auto == true &amp;&amp; correct == false</c>).</param>
	/// <returns>The classification; <see cref="ClassificationResult.Site"/> is null when the atom's path is not one the brief defines.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var keyDesc = First(line.ExpectedDescriptions);
		var acceptedDesc = First(line.ActualDescriptions);
		var keyTier = First(line.ExpectedDataTypes);
		var acceptedTier = First(line.ActualDataTypes);
		var atom = line.Atoms.FirstOrDefault(a => a.Outcome == "accepted") ?? line.Atoms.FirstOrDefault();

		var site = ClassifySite(atom, line.RawText);
		var overrideKey = site == SiteOverride ? (_overrideKeys.Contains(line.RawText) ? "yes" : "no") : string.Empty;

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);

		var keyParsed = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier));
		var acceptedParsed = string.IsNullOrWhiteSpace(acceptedDesc)
			? new ParsedFdcDescription(string.Empty, [], null)
			: FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier));

		var keyHead = SingularPhrase(keyParsed.HeadTerm);
		var acceptedHead = SingularPhrase(acceptedParsed.HeadTerm);
		var parsedName = SingularPhrase(atom?.ParsedName ?? string.Empty);
		var keyHeadPhrase = KeyHeadPhrase(keyTokens);

		var relation = string.Empty;
		var missingField = string.Empty;

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			relation = NoLabel;
		}
		else if (PackUnitRegex().IsMatch(line.RawText) && (keyState & FoodState.Canned) != FoodState.None && (acceptedState & FoodState.Canned) == FoodState.None)
		{
			relation = PackUnitState;
		}
		else if (keyHeadPhrase.Count >= 2 && parsedName.Count == 1 &&
			string.Equals(parsedName[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			relation = CompoundHeadLost;
		}
		else if (HeadsAgree(keyHead, acceptedHead))
		{
			if (keyState != acceptedState)
			{
				relation = StateMismatch;
			}
			else if (string.IsNullOrWhiteSpace(keyTier) || string.IsNullOrWhiteSpace(acceptedTier))
			{
				relation = Other;
				missingField = string.IsNullOrWhiteSpace(acceptedTier) ? "actualDataTypes" : "expectedDataTypes";
			}
			else if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
			{
				relation = RowChoiceTier;
			}
			else
			{
				relation = SameHeadOtherQualifier;
			}
		}
		else
		{
			relation = SiblingFood;
		}

		var qualifierDiff = relation == SameHeadOtherQualifier
			? QualifierDiff(keyParsed.Qualifiers, acceptedParsed.Qualifiers)
			: string.Empty;

		return new ClassificationResult(
			line.HoldoutId,
			line.LineIndex,
			line.Set,
			relation,
			site ?? string.Empty,
			overrideKey,
			acceptedTier,
			keyTier,
			acceptedState.ToString(),
			keyState.ToString(),
			atom?.ParsedName ?? string.Empty,
			string.Join(' ', keyHeadPhrase),
			acceptedDesc,
			keyDesc,
			line.RawText,
			missingField,
			qualifierDiff);
	}

	/// <summary>
	/// The key's head phrase: the leading normalised tokens of the key description, cut before the
	/// first token the production state machinery treats as a state word (a <see cref="FdcLexicon.ModifierWords"/>
	/// member, or a token <see cref="FdcMatcher.ExtractCandidateState"/>/<see cref="FdcMatcher.ExtractCandidateSatisfiers"/>
	/// reports as state-carrying). "Bread, crumbs, dry, grated, plain" → "bread crumbs";
	/// "Tomatoes, crushed, canned" → "tomato".
	/// </summary>
	/// <param name="tokens">The normalised key-description tokens.</param>
	/// <returns>The head-phrase tokens, in order.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> tokens)
	{
		ArgumentNullException.ThrowIfNull(tokens);
		var phrase = new List<string>(tokens.Count);
		foreach (var token in tokens)
		{
			if (IsStateWord(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>
	/// The production state mask for a token list: <see cref="FdcMatcher.ExtractCandidateState"/> OR
	/// <see cref="FdcMatcher.ExtractCandidateSatisfiers"/> — the same composition the matcher feeds to
	/// <c>StateAgrees</c> (FdcMatcher.cs:1155-1157).
	/// </summary>
	/// <param name="tokens">The normalised tokens.</param>
	/// <returns>The combined state mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>
	/// Whether the resolver's own exact-phrase reuse rule (F-428 P6.6) would link the parsed name to
	/// the linked master slug. Census statistic for reuse-site lines, reported on stderr.
	/// </summary>
	/// <param name="parsedName">The atom's parsed name.</param>
	/// <param name="linkedIngredientId">The linked master slug.</param>
	/// <returns>True when the production rule would reuse that master for this name.</returns>
	public static bool ReuseRuleAgrees(string parsedName, string linkedIngredientId) =>
		IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(parsedName), linkedIngredientId);

	/// <summary>
	/// The dataset tier of a trace dataType string; unknown values parse to <see cref="FdcDataset.None"/>
	/// (the curated parse path), which is the safe default for a census.
	/// </summary>
	/// <param name="dataType">The trace dataType string.</param>
	/// <returns>The FDC dataset.</returns>
	public static FdcDataset DatasetOf(string dataType) =>
		Enum.TryParse<FdcDataset>(dataType, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	private static string First(IReadOnlyList<string> values) =>
		values.Count > 0 && !string.IsNullOrWhiteSpace(values[0]) ? values[0] : string.Empty;

	private static bool HeadsAgree(IReadOnlyList<string> a, IReadOnlyList<string> b) =>
		a.Count == b.Count && a.Zip(b).All(p => string.Equals(p.First, p.Second, StringComparison.OrdinalIgnoreCase));

	private string ClassifySite(TraceAtom? atom, string rawText)
	{
		if (atom is null)
		{
			return null;
		}

		return atom.Path switch
		{
			"override" => SiteOverride,
			"curated" => SiteCurated,
			"ranker" => atom.Reused ? SiteReuse : SiteRanker,
			_ => null,
		};
	}

	private IReadOnlyList<string> SingularPhrase(string text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private string QualifierDiff(IReadOnlyList<string> keyQualifiers, IReadOnlyList<string> acceptedQualifiers)
	{
		var keySet = new HashSet<string>(keyQualifiers.Select(IngredientLineResolver.SingularizeToken), StringComparer.OrdinalIgnoreCase);
		var acceptedSet = new HashSet<string>(acceptedQualifiers.Select(IngredientLineResolver.SingularizeToken), StringComparer.OrdinalIgnoreCase);
		var keyOnly = keySet.Where(t => !acceptedSet.Contains(t)).OrderBy(t => t, StringComparer.OrdinalIgnoreCase).ToList();
		var acceptedOnly = acceptedSet.Where(t => !keySet.Contains(t)).OrderBy(t => t, StringComparer.OrdinalIgnoreCase).ToList();
		return $"key+[{string.Join(' ', keyOnly)}] accepted+[{string.Join(' ', acceptedOnly)}]";
	}

	private bool IsStateWord(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleToken.Clear();
		_singleToken.Add(token);
		return FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None;
	}
}
