{"content":"using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>Runs one census or pairs invocation over a HoldoutGate trace.</summary>
public interface IAutoWrongCensusRunner
{
	/// <summary>Runs the configured subcommand; returns the process exit code.</summary>
	/// <param name="cancellationToken">Cancellation token.</param>
	/// <returns>0 on success; 1 on a missing file, a refused set, or a malformed invocation.</returns>
	Task<int> RunAsync(CancellationToken cancellationToken);
}

/// <summary>
/// The census runner. Reads a HoldoutGate trace JSONL, classifies every <c>auto &amp;&amp; !correct</c>
/// line, and writes the TSV to <see cref="System.Console.Out"/> and the relation × site summary to
/// <see cref="System.Console.Error"/>. Refuses any trace whose record <c>set</c> is not
/// <c>debug</c> or <c>batch</c> (D-029: no sealed read).
/// </summary>
public sealed class AutoWrongCensusRunner(
	AutoWrongClassifier classifier,
	FdcNormalizer normalizer,
	IOptions<AutoWrongCensusOptions> options,
	System.IO.TextWriter output,
	System.IO.TextWriter error) : IAutoWrongCensusRunner
{
	/// <summary>Trace sets the census may read; anything else is refused (D-029).</summary>
	public static readonly FrozenSet<string> AllowedSets = FrozenSet.ToFrozenSet(["debug", "batch"], StringComparer.Ordinal);

	private readonly AutoWrongCensusOptions _options = options.Value;

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		if (_options.Command == CommandLineArgumentParser.CensusCommand)
		{
			return await RunCensusAsync(cancellationToken).ConfigureAwait(false);
		}

		if (_options.Command == CommandLineArgumentParser.PairsCommand)
		{
			return await RunPairsAsync(cancellationToken).ConfigureAwait(false);
		}

		Options.AutoWrongCensusUsage.Print();
		error.WriteLine("error: unusable arguments; expected 'census <trace.jsonl>' or 'pairs <census.tsv> <trace.jsonl>'.");
		return 1;
	}

	private async Task<int> RunCensusAsync(CancellationToken cancellationToken)
	{
		var lines = await ReadTraceAsync(_options.TracePath, error, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refused = lines.FirstOrDefault(l => !AllowedSets.Contains(l.Set));
		if (refused is not null)
		{
			error.WriteLine($"refused: trace record {refused.HoldoutId}#{refused.LineIndex} has set '{refused.Set}'; the census reads debug/batch only (D-029).");
			return 1;
		}

		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToList();
		var results = new List<ClassificationResult>(autoWrong.Count);
		var unknownSite = 0;

		foreach (var line in autoWrong)
		{
			var result = classifier.Classify(line);
			if (result.Site.Length == 0)
			{
				unknownSite++;
				error.WriteLine($"error: {line.HoldoutId}#{line.LineIndex} has unknown atom path; refusing to classify it silently.");
				continue;
			}

			results.Add(result);
		}

		WriteCensusTsv(results, output);
		WriteSummary(results, autoWrong.Count, unknownSite, error);
		return unknownSite == 0 ? 0 : 1;
	}

	private async Task<int> RunPairsAsync(CancellationToken cancellationToken)
	{
		var lines = await ReadTraceAsync(_options.TracePath, error, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refused = lines.FirstOrDefault(l => !AllowedSets.Contains(l.Set));
		if (refused is not null)
		{
			error.WriteLine($"refused: trace record {refused.HoldoutId}#{refused.LineIndex} has set '{refused.Set}'; the census reads debug/batch only (D-029).");
			return 1;
		}

		var censusRows = ReadCensusTsv(_options.CensusTsvPath, error);
		if (censusRows is null)
		{
			return 1;
		}

		var byKey = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));
		output.WriteLine("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText");

		var emitted = 0;
		var missing = 0;
		foreach (var row in censusRows)
		{
			if (!byKey.TryGetValue((row.HoldoutId, row.LineIndex), out var line))
			{
				missing++;
				error.WriteLine($"warning: census row {row.HoldoutId}#{row.LineIndex} not found in the trace; skipped.");
				continue;
			}

			var atom = line.Atoms.Count > 0 ? line.Atoms[0] : null;
			var parsedNameHead = atom is null ? string.Empty : string.Join(' ', classifier.SingularTokens(normalizer, atom.ParsedName));
			var keyHead = string.Join(' ', classifier.KeyHeadPhrase(normalizer.NormalizeToTokens(First(line.ExpectedDescriptions))));
			output.WriteLine($"{Cell(row.HoldoutId)}\t{row.LineIndex}\t{Cell(parsedNameHead)}\t{Cell(keyHead)}\t{Cell(line.RawText)}");
			emitted++;
		}

		error.WriteLine($"pairs: emitted {emitted} of {censusRows.Count} window compound/other rows ({missing} not found in the trace).");
		return 0;
	}

	private static async Task<List<TraceLine>?> ReadTraceAsync(string path, System.IO.TextWriter error, CancellationToken cancellationToken)
	{
		if (!File.Exists(path))
		{
			error.WriteLine($"error: trace file not found at '{path}'.");
			return null;
		}

		var options = new System.Text.Json.JsonSerializerOptions(JsonSerializerDefaults.Web);
		var lines = new List<TraceLine>();
		await foreach (var raw in File.ReadLinesAsync(path, cancellationToken).ConfigureAwait(false))
		{
			if (raw.Length == 0)
			{
				continue;
			}

			var line = System.Text.Json.JsonSerializer.Deserialize<TraceLine>(raw, options);
			if (line is null)
			{
				error.WriteLine($"error: unparseable trace record in '{path}': {raw[..Math.Min(raw.Length, 120)]}");
				return null;
			}

			lines.Add(line);
		}

		return lines;
	}

	private static List<(string HoldoutId, int LineIndex)>? ReadCensusTsv(string path, System.IO.TextWriter error)
	{
		if (!File.Exists(path))
		{
			error.WriteLine($"error: census TSV not found at '{path}'.");
			return null;
		}

		var rows = new List<(string, int)>();
		var header = File.ReadLines(path).FirstOrDefault();
		if (header is null)
		{
			error.WriteLine($"error: census TSV '{path}' is empty.");
			return null;
		}

		var columns = header.Split('\t').ToDictionary(c => c, c => 0, StringComparer.Ordinal);
		foreach (var (name, index) in columns)
		{
			columns[name] = index;
		}

		if (!columns.ContainsKey("holdoutId") || !columns.ContainsKey("lineIndex") || !columns.ContainsKey("blocker") || !columns.ContainsKey("route"))
		{
			error.WriteLine($"error: census TSV '{path}' is missing holdoutId/lineIndex/blocker/route columns.");
			return null;
		}

		foreach (var raw in File.ReadLines(path).Skip(1))
		{
			if (raw.Length == 0)
			{
				continue;
			}

			var cells = raw.Split('\t');
			if (cells.Length < columns.Values.Max() + 1)
			{
				continue;
			}

			var blocker = cells[columns["blocker"]];
			var route = cells[columns["route"]];
			if (blocker != "window" || (route != "compound" && route != "other"))
			{
				continue;
			}

			rows.Add((cells[columns["holdoutId"]], int.Parse(cells[columns["lineIndex"]])));
		}

		return rows;
	}

	private static void WriteCensusTsv(IReadOnlyList<ClassificationResult> results, System.IO.TextWriter output)
	{
		output.WriteLine("holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText");
		foreach (var r in results)
		{
			output.WriteLine(string.Join('\t',
				Cell(r.HoldoutId), r.LineIndex.ToString(), Cell(r.Set), Cell(r.Relation), Cell(r.Site), Cell(r.OverrideKey),
				Cell(r.AcceptedTier), Cell(r.KeyTier), Cell(r.AcceptedState), Cell(r.KeyState),
				Cell(r.ParsedName), Cell(r.KeyHead), Cell(r.AcceptedDesc), Cell(r.KeyDesc), Cell(r.RawText)));
		}
	}

	private static void WriteSummary(IReadOnlyList<ClassificationResult> results, int autoWrongCount, int unknownSite, System.IO.TextWriter error)
	{
		var set = results.Count > 0 ? results[0].Set : string.Empty;
		error.WriteLine($"autoWrongCensus set={set} autoWrongLines={autoWrongCount} classified={results.Count} unknownSite={unknownSite}");

		error.WriteLine("relation\tsite\tcount");
		foreach (var group in results.GroupBy(r => (r.Relation, r.Site)).OrderBy(g => g.Key.Relation).ThenBy(g => g.Key.Site))
		{
			error.WriteLine($"{group.Key.Relation}\t{group.Key.Site}\t{group.Count()}");
		}

		var other = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		var otherRate = results.Count > 0 ? other * 100.0 / results.Count : 0.0;
		error.WriteLine($"other rate: {other}/{results.Count} ({otherRate:0.0}%)");

		var missing = results.Where(r => r.MissingField is not null).GroupBy(r => r.MissingField).OrderBy(g => g.Key);
		error.WriteLine(missing.Any()
			? "missing fields: " + string.Join(", ", missing.Select(g => $"{g.Key}={g.Count()}")))
			: "missing fields: none");

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		error.WriteLine($"override-site lines: {overrideLines.Count}, overrideKey=yes {overrideLines.Count(r => r.OverrideKey == "yes")}");

		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		var reuseNameMismatch = 0;
		foreach (var r in reuseLines)
		{
			if (r.ParsedName.Length > 0 && !IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(r.ParsedName), r.ParsedName))
			{
				reuseNameMismatch++;
			}
		}

		error.WriteLine($"reuse-site lines: {reuseLines.Count} (ShouldReuse(parsedName, parsedName) is always true by construction; the resolver's exact-phrase rule is exercised in the unit tests)");

		var tierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		var keyHigher = tierLines.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier));
		var acceptedHigher = tierLines.Count(r => TierRank(r.AcceptedTier) > TierRank(r.KeyTier));
		error.WriteLine($"row-choice-tier: {tierLines.Count} lines, key tier higher {keyHigher}, accepted tier higher {acceptedHigher}");

		var qualifierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier).ToList();
		foreach (var r in qualifierLines)
		{
			error.WriteLine($"same-head-other-qualifier {r.HoldoutId}#{r.LineIndex}: key-only=[{string.Join(' ', r.KeyOnlyQualifiers ?? [])}] accepted-only=[{string.Join(' ', r.AcceptedOnlyQualifiers ?? [])}]");
		}
	}

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srlegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static string First(IReadOnlyList<string> values) => values.Count > 0 ? values[0] : string.Empty;

	private static string Cell(string value) => value.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');
}
