{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Resolver;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The census runner: reads one HoldoutGate trace, classifies every <c>auto &amp;&amp; !correct</c>
/// line, and writes the TSV (stdout) plus the relation × site summary (stderr). Refuses any trace
/// whose record <c>set</c> is not <c>debug</c> or <c>batch</c> (D-029: no sealed read).
/// </summary>
public sealed class AutoWrongCensusRunner(
	IOptions<AutoWrongCensusOptions> options,
	AutoWrongClassifier classifier,
	OutputWriters writers) : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private readonly AutoWrongCensusOptions _options = options.Value;

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		if (_options.Command == CommandLineArgumentParser.CensusCommand)
		{
			return await RunCensusAsync(cancellationToken).ConfigureAwait(false);
		}

		if (_options.Command == CommandLineArgumentParser.PairsCommand)
		{
			return await RunPairsAsync(cancellationToken).ConfigureAwait(false);
		}

		writers.Error.WriteLine("unusable arguments; expected: census <trace.jsonl> | pairs <census.tsv> <trace.jsonl>");
		return 1;
	}

	private async Task<int> RunCensusAsync(CancellationToken cancellationToken)
	{
		var lines = await ReadTraceAsync(_options.TracePath, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refused = RefusedSet(lines);
		if (refused is not null)
		{
			writers.Error.WriteLine($"refused: trace record set '{refused}' is not debug or batch (D-029: no sealed read)");
			return 1;
		}

		var results = new List<ClassificationResult>(lines.Count);
		foreach (var line in lines)
		{
			if (!line.Auto || line.Correct)
			{
				continue;
			}

			var result = classifier.Classify(line);
			if (result.Site.Length == 0)
			{
				writers.Error.WriteLine($"refused: {line.HoldoutId}#{line.LineIndex} has unknown atom path '{line.Atoms.FirstOrDefault()?.Path}'; cannot classify");
				return 1;
			}

			results.Add(result);
		}

		WriteCensusTsv(results);
		WriteSummary(results);
		return 0;
	}

	private async Task<int> RunPairsAsync(CancellationToken cancellationToken)
	{
		var lines = await ReadTraceAsync(_options.TracePath, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refused = RefusedSet(lines);
		if (refused is not null)
		{
			writers.Error.WriteLine($"refused: trace record set '{refused}' is not debug or batch (D-029: no sealed read)");
			return 1;
		}

		if (!File.Exists(_options.CensusTsvPath))
		{
			writers.Error.WriteLine($"census TSV not found at '{_options.CensusTsvPath}'.");
			return 1;
		}

		var wanted = ReadWindowRows(_options.CensusTsvPath);
		if (wanted is null)
		{
			return 1;
		}

		var byKey = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));
		writers.Output.WriteLine("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText");
		var emitted = 0;
		foreach (var (holdoutId, lineIndex) in wanted)
		{
			if (!byKey.TryGetValue((holdoutId, lineIndex), out var line))
			{
				writers.Error.WriteLine($"pairs: {holdoutId}#{lineIndex} is in the census but not in the trace; skipped");
				continue;
			}

			var atom = line.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase)) ?? line.Atoms.FirstOrDefault();
			var parsedNameHead = string.Join(' ', atom is null ? [] : Fold(atom.ParsedName));
			var keyHead = string.Join(' ', classifier.KeyHeadPhrase(classifier.Normalizer.NormalizeToTokens(First(line.ExpectedDescriptions))));
			writers.Output.WriteLine($"{line.HoldoutId}\t{line.LineIndex}\t{Sanitize(parsedNameHead)}\t{Sanitize(keyHead)}\t{Sanitize(line.RawText)}");
			emitted++;
		}

		writers.Error.WriteLine($"pairs: emitted {emitted} of {wanted.Count} window compound/other rows");
		return 0;
	}

	private void WriteCensusTsv(List<ClassificationResult> results)
	{
		writers.Output.WriteLine("holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText");
		foreach (var r in results)
		{
			writers.Output.WriteLine(string.Join('\t',
				Sanitize(r.HoldoutId), r.LineIndex, Sanitize(r.Set), Sanitize(r.Relation), Sanitize(r.Site), Sanitize(r.OverrideKey),
				Sanitize(r.AcceptedTier), Sanitize(r.KeyTier), Sanitize(r.AcceptedState), Sanitize(r.KeyState),
				Sanitize(r.ParsedName), Sanitize(r.KeyHead), Sanitize(r.AcceptedDesc), Sanitize(r.KeyDesc), Sanitize(r.RawText)));
		}
	}

	private void WriteSummary(List<ClassificationResult> results)
	{
		var set = results.Count > 0 ? results[0].Set : string.Empty;
		writers.Error.WriteLine($"autoWrongCensus set={set} autoWrongLines={results.Count}");

		var matrix = results
			.GroupBy(r => (r.Relation, r.Site))
			.Select(g => (Relation: g.Key.Relation, Site: g.Key.Site, Count: g.Count()))
			.OrderBy(x => x.Relation, StringComparer.Ordinal)
			.ThenBy(x => x.Site, StringComparer.Ordinal);
		writers.Error.WriteLine("relation\tsite\tcount");
		foreach (var row in matrix)
		{
			writers.Error.WriteLine($"{row.Relation}\t{row.Site}\t{row.Count}");
		}

		var other = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		writers.Error.WriteLine($"other={other}/{results.Count} ({(results.Count > 0 ? other * 100.0 / results.Count : 0.0):F1}%)");

		var missing = results.Where(r => r.MissingField is not null)
			.GroupBy(r => r.MissingField)
			.Select(g => $"{g.Key}={g.Count()}")
			.OrderBy(s => s, StringComparer.Ordinal);
		writers.Error.WriteLine($"missingFields: {(missing.Any() ? string.Join(' ', missing) : "none")}");

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		writers.Error.WriteLine($"overrideKey: yes={overrideLines.Count(r => r.OverrideKey == "yes")} no={overrideLines.Count(r => r.OverrideKey == "no")}");

		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		var reuseNotByName = 0;
		foreach (var r in reuseLines)
		{
			var line = FindLine(r);
			var atom = line?.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase)) ?? line?.Atoms.FirstOrDefault();
			if (atom is { LinkedIngredientId.Length: > 0 } && !IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(atom.ParsedName), atom.LinkedIngredientId))
			{
				reuseNotByName++;
			}
		}
		writers.Error.WriteLine($"reuse site: {reuseLines.Count} lines, {reuseNotByName} not re-accepted by the resolver's own ShouldReuse(parsedName, linkedIngredientId)");

		var tierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		var keyHigher = tierLines.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier));
		writers.Error.WriteLine($"row-choice-tier: {tierLines.Count} lines, key tier higher={keyHigher} accepted tier higher={tierLines.Count - keyHigher}");

		foreach (var r in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			writers.Error.WriteLine($"qualdiff: {r.HoldoutId}#{r.LineIndex} keyOnly=[{string.Join(' ', r.KeyOnlyQualifiers ?? [])}] acceptedOnly=[{string.Join(' ', r.AcceptedOnlyQualifiers ?? [])}]");
		}
	}

	private TraceLine? _lastLine;

	private TraceLine? FindLine(ClassificationResult r) =>
		_lastLine is { HoldoutId: var h, LineIndex: var i } && h == r.HoldoutId && i == r.LineIndex ? _lastLine : null;

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srllegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static IReadOnlyList<string> Fold(string text) =>
		Array.ConvertAll(FdcNormalizer.Default.NormalizeToTokens(text).ToArray(), t => IngredientLineResolver.SingularizeToken(t));

	private static string First(IReadOnlyList<string> values) => values.Count > 0 ? values[0] : string.Empty;

	private static string Sanitize(string value) =>
		value.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');

	private static string? RefusedSet(List<TraceLine> lines)
	{
		foreach (var line in lines)
		{
			if (!line.Set.Equals("debug", StringComparison.Ordinal) && !line.Set.Equals("batch", StringComparison.Ordinal))
			{
				return line.Set;
			}
		}

		return null;
	}

	private static List<(string HoldoutId, int LineIndex)>? ReadWindowRows(string censusTsvPath)
	{
		var lines = File.ReadLines(censusTsvPath).ToList();
		if (lines.Count == 0)
		{
			return [];
		}

		var header = lines[0].Split('\t');
		var indexOf = new Dictionary<string, int>(StringComparer.Ordinal);
		for (var i = 0; i < header.Length; i++)
		{
			indexOf[header[i]] = i;
		}

		if (!indexOf.TryGetValue("blocker", out var blockerCol) || !indexOf.TryGetValue("route", out var routeCol))
		{
			return null;
		}

		var wanted = new List<(string, int)>();
		for (var i = 1; i < lines.Count; i++)
		{
			var cells = lines[i].Split('\t');
			if (cells.Length <= Math.Max(blockerCol, routeCol))
			{
				continue;
			}

			if (cells[blockerCol] != "window" || (cells[routeCol] != "compound" && cells[routeCol] != "other"))
			{
				continue;
			}

			var holdoutId = cells.Length > indexOf["holdoutId"] ? cells[indexOf["holdoutId"]] : string.Empty;
			var lineIndex = int.TryParse(cells.Length > indexOf["lineIndex"] ? cells[indexOf["lineIndex"]] : string.Empty, out var idx) ? idx : -1;
			wanted.Add((holdoutId, lineIndex));
		}

		return wanted;
	}

	private async Task<List<TraceLine>?> ReadTraceAsync(string tracePath, CancellationToken cancellationToken)
	{
		if (!File.Exists(tracePath))
		{
			writers.Error.WriteLine($"trace not found at '{tracePath}'.");
			return null;
		}

		var lines = new List<TraceLine>();
		await foreach (var line in File.ReadLinesAsync(tracePath).WithCancellation(cancellationToken).ConfigureAwait(false))
		{
			if (string.IsNullOrWhiteSpace(line))
			{
				continue;
			}

			try
			{
				var record = JsonSerializer.Deserialize<TraceLine>(line, JsonOptions);
				if (record is not null)
				{
					lines.Add(record);
				}
			}
			catch (JsonException ex)
			{
				writers.Error.WriteLine($"trace line {lines.Count + 1} is not valid JSON: {ex.Message}");
				return null;
			}
		}

		return lines;
	}
